From 8f53b85ed8c11319eeefdc94e8dc7c1b2e3e90a7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:42:16 +0100
Subject: [PATCH] applets/notifications: don't show in panel when only
 fullscreen inhibits

Entering or leaving fullscreen briefly showed the Do Not Disturb icon in
the panel, as the window doesn't cover it yet or anymore. Inhibition that
only comes from a focused fullscreen window no longer makes it active.

BUG: 505169
---
 applets/notifications/global/Globals.qml | 46 ++++++++++++++----------
 applets/notifications/main.qml           |  2 +-
 2 files changed, 29 insertions(+), 19 deletions(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..ccf483b409 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -31,6 +31,9 @@ QtObject {
     signal timeChanged

     property bool inhibited: false
+    // Whether notifications are inhibited only because a fullscreen window is focused,
+    // which covers the panel anyway
+    property bool inhibitedByFullscreenOnly: false

     onInhibitedChanged: {
         // Explicitly update server state before potentially sending a inhibition summary,
@@ -272,32 +275,39 @@ QtObject {
         globals.plasmoid = globals.plasmoidItem.plasmoid;
     }

-    function checkInhibition() {
-        globals.inhibited = Qt.binding(function() {
-            var inhibited = false;
+    function inhibitedExceptFullscreen() {
+        var inhibited = false;

-            if (!NotificationManager.Server.valid) {
-                return false;
-            }
+        var inhibitedUntil = notificationSettings.notificationsInhibitedUntil;
+        if (!isNaN(inhibitedUntil.getTime())) {
+            inhibited |= (Date.now() < inhibitedUntil.getTime());
+        }

-            var inhibitedUntil = notificationSettings.notificationsInhibitedUntil;
-            if (!isNaN(inhibitedUntil.getTime())) {
-                inhibited |= (Date.now() < inhibitedUntil.getTime());
-            }
+        if (notificationSettings.notificationsInhibitedByApplication) {
+            inhibited |= true;
+        }

-            if (notificationSettings.notificationsInhibitedByApplication) {
-                inhibited |= true;
-            }
+        if (notificationSettings.inhibitNotificationsWhenScreensMirrored) {
+            inhibited |= notificationSettings.screensMirrored;
+        }
+
+        return inhibited;
+    }

-            if (notificationSettings.inhibitNotificationsWhenFullscreen) {
-                inhibited |= notificationSettings.fullscreenFocused;
+    function checkInhibition() {
+        globals.inhibited = Qt.binding(function() {
+            if (!NotificationManager.Server.valid) {
+                return false;
             }

-            if (notificationSettings.inhibitNotificationsWhenScreensMirrored) {
-                inhibited |= notificationSettings.screensMirrored;
+            if (inhibitedExceptFullscreen()) {
+                return true;
             }

-            return inhibited;
+            return notificationSettings.inhibitNotificationsWhenFullscreen && notificationSettings.fullscreenFocused;
+        });
+        globals.inhibitedByFullscreenOnly = Qt.binding(function() {
+            return globals.inhibited && !inhibitedExceptFullscreen();
         });
     }

diff --git a/applets/notifications/main.qml b/applets/notifications/main.qml
index 8d98753eca..986ab0ddc0 100644
--- a/applets/notifications/main.qml
+++ b/applets/notifications/main.qml
@@ -36,7 +36,7 @@ PlasmoidItem {
     readonly property int effectiveStatus: historyModel.activeJobsCount > 0
                      || historyModel.unreadNotificationsCount > 0
                      || historyModel.dismissedResidentNotificationsCount > 0
-                     || Notifications.Globals.inhibited ? PlasmaCore.Types.ActiveStatus
+                     || (Notifications.Globals.inhibited && !Notifications.Globals.inhibitedByFullscreenOnly) ? PlasmaCore.Types.ActiveStatus
                                           : PlasmaCore.Types.PassiveStatus
     onEffectiveStatusChanged: {
         if (effectiveStatus === PlasmaCore.Types.PassiveStatus) {
-- 
